{
  "name": "通用UDP组播通信接口",
  "name_en": "General-Purpose UDP Multicast Bus",
  "manufacturer": "",
  "description": "一种基于 IP/UDP 组播的虚拟通信接口，用于在实验室中的多台计算机、多个进程或分布式控制节点之间广播和接收数据。它常用于网络化消息分发、虚拟 CAN 通信测试、系统联调以及局域网内的多节点数据交换。",
  "description_en": "A virtual communication interface based on IP/UDP multicast for broadcasting and receiving data among multiple laboratory computers, processes, or distributed control nodes. It is commonly used for network message distribution, virtual CAN communication tests, system integration, and multi-node data exchange on a local area network.",
  "tag_hints": [
    "UDP multicast",
    "virtual CAN communication",
    "inter-process communication",
    "LAN message distribution",
    "distributed control systems",
    "network test interface"
  ],
  "actions": [
    {
      "action_name": "auto-send",
      "description": "向组播组发送数据。",
      "description_en": "Send data to the multicast group."
    },
    {
      "action_name": "auto-recv",
      "description": "接收组播数据并返回消息、时间戳和源地址；超时则返回空结果。",
      "description_en": "Receive multicast data and return the message, timestamp, and source address; return no result on timeout."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取内部套接字的文件描述符。",
      "description_en": "Get the file descriptor of the underlying socket."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭组播套接字并释放资源。",
      "description_en": "Close the multicast sockets and release resources."
    }
  ]
}

